#!/usr/bin/env bash
set -Eeuo pipefail;IFS=$'\n\t';D="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")"&&pwd -P)";L="$D/lab.sh";R="/tmp/reliability-atlas-les0052-model-$(id -u)";[[ ! -e "$R" ]]||exit 1;"$L" doctor;"$L" setup;trap '[[ ! -d "$R" ]]||"$L" cleanup>/dev/null' EXIT;"$L" evaluate baseline|grep -q '"decision": "reachable"';for c in overlapping-cidr missing-route asymmetric-return firewall-deny split-dns nat-exhaustion mtu-blackhole nontransitive-peering;do "$L" evaluate "$c"|grep -q '"decision": "unreachable"';done;"$L" inject-unknown;if "$L" status>/dev/null 2>&1;then exit 1;fi;"$L" clear-unknown;"$L" cleanup;trap - EXIT;[[ ! -e "$R" ]]||exit 1;printf 'verify=pass cases=9 cleanup=true runtime=model-only\n'
